//
// readback - validate a converted openPMD series against the fixture
// formulas generated by scripts/make_fixture.py.
//
// usage: readback <series-pattern> <3d|2d>
//
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <string>
#include <variant>

#include <mpi.h>

#include <openPMD/openPMD.hpp>

namespace
{
int failures = 0;

void
check(bool ok, std::string const & what)
{
    if (!ok)
    {
        std::printf("FAIL: %s\n", what.c_str());
        ++failures;
    }
}

double
fieldValue(uint64_t step, uint64_t i, uint64_t j, uint64_t k)
{
    return double(step) * 1000.0 + double(i) + 2.0 * double(j)
        + 3.0 * double(k);
}

void
checkD(double a, double b, std::string const & what)
{
    check(std::abs(a - b) <= 1e-12 * std::max(1.0, std::abs(a)), what);
}

void
checkV(std::vector<double> const & a, std::vector<double> const & b,
    std::string const & what)
{
    bool ok = a.size() == b.size();
    for (size_t i = 0; ok && i < a.size(); ++i)
        ok = std::abs(a[i] - b[i]) <= 1e-9 * std::max(1.0, std::abs(b[i]));
    check(ok, what);
}

void
validate3d(openPMD::Series & series, openPMD::Iteration & it, uint64_t step)
{
    using namespace openPMD;

    checkD(it.time<double>(), double(step) * 1.5e-15, "iteration time");
    checkD(it.dt<double>(), 5e-17 / double(step), "iteration dt");

    // Yee components keep their SDF ids as scalar records, each with an
    // exact grid position derived from its stagger
    auto & ex = it.meshes["ex"];
    auto & ey = it.meshes["ey"];
    auto & bz = it.meshes["bz"];
    auto const scalar = RecordComponent::SCALAR;
    check(ex[scalar].getExtent() == Extent{8, 6, 5}, "extent of ex");
    check(ey[scalar].getExtent() == Extent{8, 6, 5}, "extent of ey");
    check(bz[scalar].getExtent() == Extent{8, 6, 5}, "extent of bz");

    auto const dxx = ex[scalar].loadChunk<double>({0, 0, 0}, {8, 6, 5});
    auto const dyy = ey[scalar].loadChunk<double>({0, 0, 0}, {8, 6, 5});
    auto const dzz = bz[scalar].loadChunk<double>({0, 0, 0}, {8, 6, 5});

    auto const spacing =
        ex.getAttribute("gridSpacing").get<std::vector<double>>();
    auto const offset =
        ex.getAttribute("gridGlobalOffset").get<std::vector<double>>();
    checkV(spacing, {0.1, 0.2, 0.3}, "gridSpacing");
    checkV(offset, {0.0, 1.0, -2.0}, "gridGlobalOffset");
    check(ex.containsAttribute("sdf_axis_x"), "axis array attribute");

    auto const xPos =
        ex.getAttribute("position").get<std::vector<double>>();
    auto const yPos =
        ey.getAttribute("position").get<std::vector<double>>();
    auto const bPos =
        bz.getAttribute("position").get<std::vector<double>>();
    checkV(xPos, {0.5, 0.0, 0.0}, "ex grid position from stagger");
    checkV(yPos, {0.0, 0.5, 0.0}, "ey grid position from stagger");
    checkV(bPos, {0.0, 0.0, 0.5}, "bz grid position from stagger");

    auto & el = it.particles["el"];
    auto const np = el["position"]["x"].getExtent()[0];
    check(np == 103, "particle count");
    auto const px = el["position"]["x"].loadChunk<double>({0}, {np});
    auto const py = el["position"]["y"].loadChunk<double>({0}, {np});
    auto const pz = el["position"]["z"].loadChunk<double>({0}, {np});
    auto const pw = el["weighting"][RecordComponent::SCALAR].loadChunk<double>(
        {0}, {np});

    series.flush(); // complete all loads

    for (uint64_t p = 0; p < np && failures <= 8; ++p)
    {
        checkD(px.get()[p], 0.5 * double(p) + double(step), "position x");
        checkD(py.get()[p], -double(p), "position y");
        checkD(pz.get()[p], double(p) / 8.0, "position z");
        checkD(pw.get()[p], 4.0, "weighting");
    }

    for (uint64_t k = 0; k < 5 && failures <= 8; ++k)
    {
        for (uint64_t j = 0; j < 6 && failures <= 8; ++j)
        {
            for (uint64_t i = 0; i < 8 && failures <= 8; ++i)
            {
                uint64_t const idx = i * 30 + j * 5 + k; // C order
                checkD(dxx.get()[idx], fieldValue(step, i, j, k), "E/x");
                checkD(dyy.get()[idx],
                    fieldValue(step, i, j, k) + 1000.0, "E/y");
                checkD(dzz.get()[idx],
                    fieldValue(step, i, j, k) + 100.0, "B/z");
            }
        }
    }
}

void
validate2d(openPMD::Series & series, openPMD::Iteration & it, uint64_t step)
{
    using namespace openPMD;

    checkD(it.time<double>(), 0.25, "2d time");
    checkD(it.dt<double>(), 1e-18, "2d dt");

        // 2d fixture: ex/ey share dims+stagger -> one vector record E
    auto const ex = it.meshes["E"]["x"].loadChunk<double>({0, 0}, {4, 3});
    auto & ion = it.particles["ion"];
    auto const np = ion["position"]["x"].getExtent()[0];
    check(np == 7, "ion count");
    auto const ix = ion["position"]["x"].loadChunk<double>({0}, {np});

    series.flush();

    for (uint64_t j = 0; j < 3; ++j)
    {
        for (uint64_t i = 0; i < 4; ++i)
        {
            uint64_t const idx = i * 3 + j; // C order
            checkD(ex.get()[idx],
                double(step) * 10.0 + double(i) + 2.0 * double(j), "2d E/x");
        }
    }
    for (uint64_t p = 0; p < np; ++p)
        checkD(ix.get()[p], 1.5 * double(p), "ion x");
}
} // namespace

int
main(int argc, char * * argv)
{
    if (argc < 3)
    {
        std::fprintf(stderr, "usage: readback <series> <3d|2d>\n");
        return 2;
    }
    std::string const mode = argv[2];

    MPI_Init(&argc, &argv);
    try
    {
        openPMD::Series series(argv[1], openPMD::Access::READ_ONLY,
            MPI_COMM_WORLD);

        auto const expected = mode == "3d" ? 2 : 1;
        check(series.iterations.size() == size_t(expected),
            "iteration count");
        for (auto & [step, it] : series.iterations)
        {
            if (mode == "3d")
                validate3d(series, it, step);
            else
                validate2d(series, it, step);
        }
    }
    catch (std::exception const & e)
    {
        std::printf("FAIL: exception: %s\n", e.what());
        ++failures;
    }
    MPI_Finalize();

    if (failures == 0)
    {
        std::printf("READBACK OK\n");
        return 0;
    }
    std::printf("%d failure(s)\n", failures);
    return 1;
}
